// Part 2: Container definitions, similar to the PDU definitions in 11.2 for RRC messages
// In alphabetical order

// ***************************************************
//
// Handover to UTRAN information
//
// ***************************************************
typedef struct InterRATHandoverInfoWithInterRATCapabilities_r3 {
    unsigned short  choice;
#       define      InterRATHandoverInfoWithInterRATCapabilities_r3_r3_chosen 1
#       define      InterRATHandoverInfoWithInterRATCapabilities_r3_criticalExtensions_chosen 2
    union _union {
        struct _seq1132 {
            unsigned char   bit_mask;
#               define      r3_v390NonCriticalExtensions_present 0x80
		// IE InterRATHandoverInfoWithInterRATCapabilities-r3-IEs also 
		// includes non critical extensions
            InterRATHandoverInfoWithInterRATCapabilities_r3_IEs interRATHandoverInfo_r3;
            struct _seq1131 {
                unsigned char   bit_mask;
#                   define      v390NonCriticalExtensions_v690NonCriticalExtensions_present 0x80
                InterRATHandoverInfoWithInterRATCapabilities_v390ext_IEs interRATHandoverInfoWithInterRATCapabilities_v390ext;
			// Reserved for future non critical extension
                struct _seq1130 {
                    unsigned char   bit_mask;
#                       define      v390NonCriticalExtensions_v690NonCriticalExtensions_v860NonCriticalExtensions_present 0x80
                    InterRATHandoverInfoWithInterRATCapabilities_v690ext_IEs interRATHandoverInfoWithInterRATCapabilities_v690ext;
                    struct _seq1129 {
                        unsigned char   bit_mask;
#                           define      v690NonCriticalExtensions_v860NonCriticalExtensions_v920NonCriticalExtensions_present 0x80
                        InterRATHandoverInfoWithInterRATCapabilities_v860ext_IEs interRATHandoverInfoWithInterRATCapabilities_v860ext;
                        struct _seq1128 {
                            unsigned char   bit_mask;
#                               define      v860NonCriticalExtensions_v920NonCriticalExtensions_nonCriticalExtensions_present 0x80
                            InterRATHandoverInfoWithInterRATCapabilities_v920ext_IEs interRATHandoverInfoWithInterRATCapabilities_v920ext;
                            _seq31          nonCriticalExtensions;  
                                  /* optional; set in bit_mask
         * v860NonCriticalExtensions_v920NonCriticalExtensions_nonCriticalExtensions_present if
         * present */
                        } v920NonCriticalExtensions;  /* optional; set in
                                   * bit_mask
             * v690NonCriticalExtensions_v860NonCriticalExtensions_v920NonCriticalExtensions_present if
             * present */
                    } v860NonCriticalExtensions;  /* optional; set in bit_mask
             * v390NonCriticalExtensions_v690NonCriticalExtensions_v860NonCriticalExtensions_present if
             * present */
                } v690NonCriticalExtensions;  /* optional; set in bit_mask
               * v390NonCriticalExtensions_v690NonCriticalExtensions_present if
               * present */
            } v390NonCriticalExtensions;  /* optional; set in bit_mask
                                      * r3_v390NonCriticalExtensions_present if
                                      * present */
        } r3;  /* to choose, set choice to
                * InterRATHandoverInfoWithInterRATCapabilities_r3_r3_chosen */
        _seq31          criticalExtensions;  /* to choose, set choice to
 * InterRATHandoverInfoWithInterRATCapabilities_r3_criticalExtensions_chosen */
    } u;
} InterRATHandoverInfoWithInterRATCapabilities_r3;

